			/// // Listen to all notifications posted for a single object
			/// var token = NSFileHandle.Notifications.ObserveReadToEndOfFileCompletion (objectToObserve, (notification) => {
			///   Console.WriteLine ($"Observed ReadToEndOfFileCompletionNotification for {nameof (objectToObserve)}!");
			/// };
			/// 
			/// // Stop listening for notifications
			/// token.Dispose ();
			/// ]]></code>
			///   </example>
			/// </remarks>
			public static NSObject ObserveReadToEndOfFileCompletion (NSObject objectToObserve, EventHandler<Foundation.NSFileHandleReadEventArgs> handler)
			{
				return NSNotificationCenter.DefaultCenter.AddObserver (ReadToEndOfFileCompletionNotification, notification => handler (null, new Foundation.NSFileHandleReadEventArgs (notification)), objectToObserve);
			}
		}
	} /* class NSFileHandle */
}
